data class Task(val id: Int, val title: String, val done: Boolean = false)

class TaskManager {
    private val tasks = mutableListOf<Task>()
    private var next = 1

    fun add(title: String): Task = Task(next++, title).also { tasks += it }

    fun complete(id: Int): Boolean {
        val i = tasks.indexOfFirst { it.id == id }
        if (i < 0) return false
        tasks[i] = tasks[i].copy(done = true)
        return true
    }

    fun pending() = tasks.filter { !it.done }
}

fun main() {
    val m = TaskManager()
    m.add("Learn Kotlin")
    m.add("Build project")
    m.complete(1)
    println(m.pending().size)
    println(m.complete(99))
}

import kotlin.test.Test
import kotlin.test.assertFalse

class TaskManagerTest {
    @Test
    fun `complete unknown id returns false`() {
        val m = TaskManager()
        assertFalse(m.complete(5))
    }
}
